import{_ as t,o,c as a,a2 as d}from"./chunks/framework.B2OIHwwP.js";const g=JSON.parse('{"title":"Level editor spec","description":"","frontmatter":{},"headers":[],"relativePath":"guide/editor.md","filePath":"guide/editor.md"}'),l={name:"guide/editor.md"};function r(s,e,i,n,c,h){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="level-editor-spec" tabindex="-1">Level editor spec <a class="header-anchor" href="#level-editor-spec" aria-label="Permalink to &quot;Level editor spec&quot;">​</a></h1><p>Status: <strong>first version built</strong> (levels A and B: warnings and Play). Written from the answers of the game designer. Items marked <code>_TBD_</code> are undecided and may change.</p><p>The editor lives in the same repo as its own page, served next to the game at <code>&lt;pagesUrl&gt;/editor/</code> (beside <code>/demo/</code> and <code>/docs/</code>). It is a Three.js-era custom addition; the Phaser template does not cover it.</p><p>Source: <code>game/editor/</code> (<code>main.js</code>, <code>template.html</code>, <code>build.mjs</code>). <code>npm run build</code> builds the game and the editor; <code>npm run build:site</code> copies the editor to <code>/editor/</code>. Level rules shared with the game live in <code>game/src/levelcfg.js</code>; the built-in 15 levels are <code>game/src/levels.json</code> (regenerate with <code>node game/tools/export-levels.mjs</code>).</p><h2 id="_0-how-it-works-in-practice" tabindex="-1">0. How it works in practice <a class="header-anchor" href="#_0-how-it-works-in-practice" aria-label="Permalink to &quot;0. How it works in practice&quot;">​</a></h2><ul><li>First launch: choose a folder (Chrome/Edge) or Browser storage, then press <strong>Add the 15 built-in levels</strong>.</li><li>Edit a level, press <strong>Save</strong> (Ctrl/Cmd+S). Each save keeps the last 10 versions.</li><li><strong>Play</strong> opens the game over the editor with the open level. Back and Restart are in the top bar. <strong>Seed</strong>: the same seed gives the same fish layout at the start; after that fish move with real time, so a run is not frame-for-frame identical.</li><li><strong>Collections</strong> (Organiser tab) order levels. <strong>Export levels.json</strong> downloads the collection as one file; put it at <code>game/src/levels.json</code> and rebuild to ship those levels in the game. The published game does not read the editor&#39;s folder by itself.</li><li><strong>Reference level (1-15)</strong> (<code>refLevel</code>): a few internal rules are not level fields yet (which random events appear, how many big fish swim around, how far look-alike colours are shifted). The level borrows them from the built-in level with that number. Auto-fill sets it from Difficulty (Easy 3, Medium 8, Hard 13).</li><li>The preview is a 3D sketch (cylinder tank, dots for fish) and does not show real fish positions.</li><li>Known limits of this version: a level can have at most 2 bounty tanks (one of each kind); the logo is a text placeholder until the official Athena asset is added; no simulation (level C).</li></ul><h2 id="_1-what-a-level-is" tabindex="-1">1. What a level is <a class="header-anchor" href="#_1-what-a-level-is" aria-label="Permalink to &quot;1. What a level is&quot;">​</a></h2><p>Fishy Find levels are <strong>parameter sets, not hand-placed layouts</strong>. Fish positions are random when the game runs, so the editor edits parameters, previews them, and lets the designer play the level. It is not a grid or voxel editor.</p><table tabindex="0"><thead><tr><th>Group</th><th>Field (file key)</th><th>Label in editor</th><th>Notes</th></tr></thead><tbody><tr><td>Goal</td><td><code>goal</code></td><td>Target tanks</td><td>Number of target tanks</td></tr><tr><td>Goal</td><td><code>per</code></td><td><strong>Fish per tank</strong></td><td>1, 2 or 3; same for every normal tank. A level file can instead list <code>tanks</code>, the fish of each tank (e.g. <code>[1,1,2,3]</code>); then <code>goal</code> is its length</td></tr><tr><td>Goal</td><td><code>bounty[]</code></td><td>Bounty tanks</td><td>List of ×1 tanks, each <code>tiny</code>, <code>camo</code> or <code>fast</code>. They appear after the first 2 tanks</td></tr><tr><td>Fish</td><td><code>species</code></td><td>Species</td><td>Default <code>2 × goal</code> (target species + decoy species)</td></tr><tr><td>Fish</td><td><code>decoyFish</code></td><td>Decoy fish</td><td>Extra non-target fish</td></tr><tr><td>Fish</td><td><code>look</code></td><td>Look-alike level</td><td>0, 1, 2 (how close decoys are to targets)</td></tr><tr><td>Fish</td><td><code>sizeK</code>, <code>speedK</code></td><td>Fish size, Fish speed</td><td>Multipliers</td></tr><tr><td>Obstacles</td><td><code>urchin</code>, <code>jelly</code>, <code>squid</code>, <code>clam</code>, <code>swarm</code></td><td>Obstacles</td><td>Counts; swarm is on/off</td></tr><tr><td>Pump tube</td><td><code>tube.enabled</code></td><td>Tube</td><td>On/off</td></tr><tr><td>Pump tube</td><td><code>tube.extraFish</code></td><td>Extra fish</td><td>Fish waiting in the tube</td></tr><tr><td>Pump tube</td><td><code>tube.waves[]</code></td><td>Waves</td><td>Each wave: <code>afterTanks</code> (pump after N target tanks are done) and <code>holdLast</code> (keep the last fish of a tank)</td></tr><tr><td>Pump tube</td><td><code>tube.autoPumpWhenStuck</code>, <code>tube.stuckDelaySec</code></td><td>Auto-pump</td><td>Default on, 2.5 s</td></tr><tr><td>Boosters</td><td><code>backup</code>, <code>hint</code>, <code>clear</code></td><td>Backup / Hint / Clear Backup</td><td>On/off</td></tr><tr><td>Events</td><td><code>eventGap</code>, <code>feed</code>, <code>feedGap</code>, <code>swarmGap</code>, <code>startle</code>, <code>startleGap</code></td><td>Events</td><td>Seconds ranges</td></tr><tr><td>Look</td><td><code>theme</code></td><td>Theme</td><td>Default <code>floor((level-1)/3)</code>; can be set by hand</td></tr></tbody></table><p>Defaults for every field come from the game&#39;s current <code>levelConfig()</code>. A level file may leave a field out to use the default.</p><p><strong>Level file:</strong> JSON with <code>schema: &quot;spot-a-fish-level&quot;</code> and <code>version: 1</code> (required), <code>id</code> and <code>name</code> (required), then the fields above. Level info (not gameplay): <code>status</code>, <code>difficulty</code>, <code>category</code>.</p><p><strong>Out of editor scope:</strong> progress, stars and tutorial flags (<code>localStorage</code>), shop or currency (none exists), fish art and sounds.</p><h2 id="_2-validation-warnings-level-1" tabindex="-1">2. Validation (warnings, level 1) <a class="header-anchor" href="#_2-validation-warnings-level-1" aria-label="Permalink to &quot;2. Validation (warnings, level 1)&quot;">​</a></h2><p>The editor shows a warning for each of these:</p><ul><li>Total fish in the tank at start is more than <code>FISH_CAP</code> (40), or more than <code>TUBE_INIT</code> (40) when the tube is on.</li><li><code>species</code> is less than <code>2 × goal</code>, or more than the 23 species available.</li><li>Fish needed (<code>goal × per</code> plus bounty tanks) is more than the fish available (tank plus tube).</li><li>A tube wave has <code>afterTanks</code> larger than the number of target tanks.</li><li>A bounty tank is set but fewer than 2 normal tanks exist.</li><li>Missing required fields, duplicate <code>id</code>.</li></ul><p><code>_TBD_</code>: further rules (&quot;unwinnable&quot; cases, difficulty rules) will be added later by the designer.</p><h2 id="_3-level-generation" tabindex="-1">3. Level generation <a class="header-anchor" href="#_3-level-generation" aria-label="Permalink to &quot;3. Level generation&quot;">​</a></h2><ul><li>The designer sets <strong>Target tanks</strong>, <strong>Fish per tank</strong> and <strong>Difficulty</strong>.</li><li><strong>Auto-fill</strong> fills species (<code>2 × goal</code>), decoys, obstacles and tube from the existing <code>levelConfig()</code> formulas. This is a <strong>placeholder rule</strong> to be replaced later.</li><li>The designer then edits any field by hand.</li><li>Fish positions are not generated by the editor; the game randomises them at runtime.</li></ul><h2 id="_4-storage" tabindex="-1">4. Storage <a class="header-anchor" href="#_4-storage" aria-label="Permalink to &quot;4. Storage&quot;">​</a></h2><ul><li>A folder on disk (File System Access API: Chrome and Edge only) or <strong>Browser storage</strong> for trying things out.</li><li>Layout: <code>levels/&lt;id&gt;.json</code>, <code>history/&lt;id&gt;/</code> (10 most recent versions), <code>collections/</code>, <code>drafts/</code>.</li><li>Import never overwrites: a duplicate id is renamed. Delete and id rename are supported.</li></ul><h2 id="_5-level-management" tabindex="-1">5. Level management <a class="header-anchor" href="#_5-level-management" aria-label="Permalink to &quot;5. Level management&quot;">​</a></h2><ul><li>Per level: <strong>Name</strong>, <strong>Id</strong>, <strong>Status</strong> (Draft / Ready / Retired), <strong>Difficulty</strong> (Easy / Medium / Hard, set by hand), <strong>Category</strong> (for example Tutorial, Normal, Bounty, Boss).</li><li>Levels are ordered into <strong>collections</strong> in the Organiser tab (for example &quot;Main 1–15&quot;). Organiser behaviour and the Add level dialog follow the fixed defaults below.</li></ul><h2 id="_6-checking-a-level" tabindex="-1">6. Checking a level <a class="header-anchor" href="#_6-checking-a-level" aria-label="Permalink to &quot;6. Checking a level&quot;">​</a></h2><ul><li><strong>Level A, built first:</strong> warnings for basic data errors (section 2).</li><li><strong>Level B, built first:</strong> a <strong>Play</strong> button that runs the level in the editor.</li><li><strong>Level C, later:</strong> a simulation tool that estimates win rate and difficulty. What counts as &quot;difficult&quot; is <code>_TBD_</code>.</li></ul><h2 id="_7-play-test" tabindex="-1">7. Play test <a class="header-anchor" href="#_7-play-test" aria-label="Permalink to &quot;7. Play test&quot;">​</a></h2><ul><li>Play opens the game over the editor, with <strong>Back</strong> and <strong>Restart</strong>.</li><li>The game reads the editor&#39;s level JSON <strong>directly</strong>; no conversion step. <code>game/src/main.js</code> will load levels from JSON; the current 15 levels are exported to JSON as the default data, so the game runs as before without the editor.</li><li>Play test does not write <code>localStorage</code> progress and does not award stars.</li><li>A <strong>Seed</strong> box (optional, empty = random) makes fish layout repeatable. This needs the game to use a seeded random generator in place of <code>Math.random</code> for level setup.</li></ul><h2 id="_8-look-and-layout-fixed-defaults" tabindex="-1">8. Look and layout (fixed defaults) <a class="header-anchor" href="#_8-look-and-layout-fixed-defaults" aria-label="Permalink to &quot;8. Look and layout (fixed defaults)&quot;">​</a></h2><ul><li>Athena logo (orange on dark theme, black on light). Dark and light theme with a Theme toggle, choice remembered. Colour tone as in the Fish Ball editor.</li><li>Level list on the left, main work area in the centre, properties (inspector) on the right. Panels are collapsible and resizable, state remembered.</li></ul><h3 id="organiser-add-level-dialog" tabindex="-1">Organiser: Add level dialog <a class="header-anchor" href="#organiser-add-level-dialog" aria-label="Permalink to &quot;Organiser: Add level dialog&quot;">​</a></h3><ol><li>Lists only levels not in the current collection, one row per level (name, size info, difficulty), with a tick box.</li><li>A search box filters by level name.</li><li>Buttons <strong>Add all levels</strong> and <strong>Add selected levels</strong>, with an &quot;N of M selected&quot; line.</li><li><strong>Add selected levels</strong> is dimmed while nothing is ticked.</li><li>Either add button closes the dialog; new levels are appended at the end in the order listed.</li><li>If every level is already in the collection, the dialog shows &quot;All levels are already in this collection.&quot; and no add buttons.</li><li>An X button closes the dialog without adding.</li></ol>',30)])])}const f=t(l,[["render",r]]);export{g as __pageData,f as default};
